package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/gin-gonic/gin"
	_ "github.com/lib/pq"
)

type CredentialCache struct {
	mu    sync.RWMutex
	store map[string]*CachedCred
}

type CachedCred struct {
	AccessKeyID     string    `json:"access_key_id"`
	SecretAccessKey string    `json:"secret_access_key"`
	SessionToken    string    `json:"session_token"`
	Expiration      time.Time `json:"expiration"`
	RequestedBy     string    `json:"requested_by"`
	RequestedAt     time.Time `json:"requested_at"`
}

var credCache = &CredentialCache{
	store: make(map[string]*CachedCred),
}

func main() {
	r := gin.Default()

	r.GET("/health", healthCheck)
	r.POST("/api/v1/credentials/rotate", rotateCredentials)
	r.GET("/api/v1/credentials/status", getCredentialStatus)
	r.GET("/debug/cache", debugCacheContents)
	r.POST("/api/v1/data/query", executeQuery)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	r.Run(":" + port)
}

func healthCheck(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{"status": "healthy", "timestamp": time.Now()})
}

func rotateCredentials(c *gin.Context) {
	var req struct {
		ServiceName string `json:"service_name" binding:"required"`
		RoleARN     string `json:"role_arn" binding:"required"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	// Simulate STS AssumeRole - in production this calls AWS STS
	newCred := &CachedCred{
		AccessKeyID:     fmt.Sprintf("AKIA%s%d", req.ServiceName, time.Now().UnixNano()),
		SecretAccessKey: fmt.Sprintf("secret_%s_%d", req.ServiceName, time.Now().UnixNano()),
		SessionToken:    fmt.Sprintf("FwoGZX...%d", time.Now().UnixNano()),
		Expiration:      time.Now().Add(1 * time.Hour),
		RequestedBy:     c.GetHeader("X-Caller-Identity"),
		RequestedAt:     time.Now(),
	}

	// BUG: credentials are cached indefinitely - old entries never evicted
	// This causes unbounded memory growth AND credential exposure
	credCache.mu.Lock()
	key := fmt.Sprintf("%s_%d", req.ServiceName, time.Now().UnixNano())
	credCache.store[key] = newCred
	credCache.mu.Unlock()

	c.JSON(http.StatusOK, gin.H{
		"access_key_id": newCred.AccessKeyID,
		"expiration":    newCred.Expiration,
		"cache_key":     key,
	})
}

func getCredentialStatus(c *gin.Context) {
	credCache.mu.RLock()
	count := len(credCache.store)
	credCache.mu.RUnlock()
	c.JSON(http.StatusOK, gin.H{"cached_credentials": count})
}

// VULNERABILITY: Exposes all cached credentials including secrets
// No authentication check, no rate limiting
func debugCacheContents(c *gin.Context) {
	credCache.mu.RLock()
	defer credCache.mu.RUnlock()

	results := make(map[string]*CachedCred)
	for k, v := range credCache.store {
		results[k] = v
	}
	// Returns full secret keys and session tokens
	c.JSON(http.StatusOK, results)
}

func executeQuery(c *gin.Context) {
	var req struct {
		Query string `json:"query" binding:"required"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	dsn := os.Getenv("DATABASE_URL")
	db, err := sql.Open("postgres", dsn)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "db connection failed"})
		return
	}
	defer db.Close()

	// Parameterized query - NOT vulnerable to SQLi
	rows, err := db.Query(req.Query)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	defer rows.Close()

	c.JSON(http.StatusOK, gin.H{"status": "executed"})
}
